#!/usr/bin/env bash
# E2E test for local optimization config feature.
#
# Prerequisites (must exist before running):
#   temp/optimization_config/percent.json  — generated by 'yarn generate-cache'
#   filters/filter_1_Russian/filter.txt    — source file in repo
#
# Test steps:
#   1. Pick 2 network rules ('||' prefix) from filter_1_Russian/filter.txt:
#        FILTERED_RULE (1st match) — set to hits=0    in stats.json
#        KEPT_RULE     (2nd match) — set to hits=9999 in stats.json
#   2. Create temp/optimization_config/filters/1/stats.json with threshold hits=1:
#        hits < 1  → optimizer removes the rule from compiled output
#        hits >= 1 → optimizer keeps  the rule in  compiled output
#      (Node is used instead of sed/heredoc to handle special chars: $, *, ^)
#   3. Run 'yarn build:local --include=1 --no-patches-prepare'.
#      build:local calls generateStats() which detects local stats file and uses it.
#   4. Assert FILTERED_RULE is absent  from platforms/**/*_optimized.txt → PASS/FAIL
#   5. Assert KEPT_RULE    is present  in  platforms/**/*_optimized.txt → PASS/FAIL
#      (non-optimized 1.txt always contains all rules, so only _optimized files are checked)
#   6. Remove created stats.json on any exit via trap.
set -euo pipefail

cd "$(dirname "$0")/../../.."  # repo root (script is at scripts/build/__tests__/)

PERCENT_JSON="temp/optimization_config/percent.json"
STATS="temp/optimization_config/filters/1/stats.json"
FILTER_TXT="filters/filter_1_Russian/filter.txt"
STATS_CREATED=0

cleanup() {
    if [ "$STATS_CREATED" -eq 1 ] && [ -f "$STATS" ]; then
        rm -f "$STATS"
        echo "Removed test stats.json"
    fi
}
trap cleanup EXIT

[ -f "$PERCENT_JSON" ] || { echo "ERROR: $PERCENT_JSON missing. Run 'yarn generate-cache' first."; exit 1; }
[ -f "$FILTER_TXT" ]   || { echo "ERROR: $FILTER_TXT missing."; exit 1; }

# Strip \r: filter.txt has CRLF line endings; grep on macOS returns lines with \r,
# which would cause a mismatch against the trimmed rule text produced by the compiler.
FILTERED_RULE=$(grep -m1 '^||' "$FILTER_TXT" | tr -d '\r')
[ -n "$FILTERED_RULE" ] || { echo "ERROR: No network rules found in $FILTER_TXT"; exit 1; }
KEPT_RULE=$(grep -m2 '^||' "$FILTER_TXT" | tail -n1 | tr -d '\r')
[ -n "$KEPT_RULE" ]     || { echo "ERROR: Need at least 2 network rules in $FILTER_TXT"; exit 1; }
[ "$FILTERED_RULE" != "$KEPT_RULE" ] || { echo "ERROR: Only one unique network rule found"; exit 1; }
echo "Rule to filter (hits=0):    $FILTERED_RULE"
echo "Rule to keep   (hits=9999): $KEPT_RULE"

mkdir -p "$(dirname "$STATS")"

# Write stats.json via Node to safely handle special characters in rule text.
# Wide bounds [0,100]: only 2 rules are in stats out of ~17k in the real filter,
# so ~100% of rules are kept — set [0,100] so the percent check always passes.
FILTERED_RULE="$FILTERED_RULE" KEPT_RULE="$KEPT_RULE" STATS_PATH="$STATS" node --input-type=commonjs -e "
const fs = require('fs');
const filteredRule = process.env.FILTERED_RULE;
const keptRule = process.env.KEPT_RULE;
const statsPath = process.env.STATS_PATH;
fs.writeFileSync(statsPath, JSON.stringify({
    percent: 99,
    minPercent: 0,
    maxPercent: 100,
    strict: false,
    groups: [{
        config: { type: 'BASIC', scope: 'GENERIC', hits: 1 },
        rules: { [filteredRule]: 0, [keptRule]: 9999 },
    }],
}, null, 2) + '\n');
"
STATS_CREATED=1

yarn build:local --include=1 --no-patches-prepare

FAIL=0
# Check only *_optimized.txt files: the non-optimized 1.txt always contains all rules
if grep -rqF "$FILTERED_RULE" --include='*_optimized.txt' platforms/ 2>/dev/null; then
    echo "FAIL: rule still present in optimized output: $FILTERED_RULE"
    FAIL=1
fi
if ! grep -rqF "$KEPT_RULE" --include='*_optimized.txt' platforms/ 2>/dev/null; then
    echo "FAIL: rule missing from optimized output: $KEPT_RULE"
    FAIL=1
fi

[ "$FAIL" -eq 0 ] && echo "PASS: filtered rule absent, kept rule present"
exit "$FAIL"
